package main

import (
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/argocd"
	"github.com/integrio-intropy/intropy-cli/internal/deploy"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/spf13/cobra"
	"golang.org/x/term"
)

type deployFlags struct {
	env          string
	domain       string
	system       string
	gitopsRepo   string
	argocdServer string
	plan         bool
	allowDirty   bool
	noWait       bool
	timeout      time.Duration
	output       string
}

var deployFlagValues = deployFlags{output: deploy.OutputPlain}

var deployCmd = &cobra.Command{
	Use:   "deploy <component> [version]",
	Short: "Pin a component's image digest into an environment",
	Long: "Pin the image digests for a component into one environment's kustomize overlay in the GitOps " +
		"repository.\n\n" +
		"Without a version the commit comes from HEAD in the current source repository, which must be clean " +
		"and pushed — CI builds pushed commits, so an unpushed one has no image — and the digests come from the " +
		"tags CI published for it.\n\n" +
		"With a version the digests come from that release's manifest instead. The release already recorded " +
		"them, so no source repository is read and the command works from any directory. When the target " +
		"environment declares promotesFrom, the plan also says whether those digests are what the upstream " +
		"environment is already running.\n\n" +
		"The component is located by searching the GitOps repository for domains/*/*/<component>; pass --domain " +
		"and --system if the name is ambiguous.\n\n" +
		"With --plan the overlay is rendered and diffed but nothing is written to git. After pushing, the command " +
		"waits for ArgoCD to apply the new revision; --no-wait skips that, and environments that sync manually " +
		"never wait.\n\n" +
		"The subcommand names win over the component argument, so a component actually called diff, init, promote, " +
		"status or sync is not reachable this way.",
	Args:              cobra.RangeArgs(1, 2),
	ValidArgsFunction: completeDeployComponents,
	RunE: func(cmd *cobra.Command, args []string) error {
		if err := validateOutputFlag(deployFlagValues.output, deploy.OutputPlain, deploy.OutputJSON); err != nil {
			return err
		}
		if deployFlagValues.env == "" {
			return newUsageErrorf("--env is required")
		}
		// Not named version: that is the package-level CLI version, and
		// shadowing it here would put the release into the user agent.
		releaseVersion := versionArg(args)
		// Ignoring a flag that cannot apply would leave the impression that a
		// working-tree check was waived when none was ever run.
		if releaseVersion != "" && deployFlagValues.allowDirty {
			return newUsageErrorf("--allow-dirty has no meaning when deploying a release: a release records the digests, so no working tree is read")
		}

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()

		return deploy.Run(ctx, deploy.Options{
			Component:    args[0],
			Version:      releaseVersion,
			Domain:       deployFlagValues.domain,
			System:       deployFlagValues.system,
			Environment:  deployFlagValues.env,
			GitopsRepo:   deployFlagValues.gitopsRepo,
			ArgocdServer: deployFlagValues.argocdServer,
			PlanOnly:     deployFlagValues.plan,
			AllowDirty:   deployFlagValues.allowDirty,
			NoWait:       deployFlagValues.noWait,
			Timeout:      deployFlagValues.timeout,
			OutputFormat: deployFlagValues.output,
			Color:        useColor(cmd),
			UserAgent:    "intropy-cli/" + version,
			Stdout:       cmd.OutOrStdout(),
			Stderr:       cmd.ErrOrStderr(),
		})
	},
}

// versionArg returns the optional release version.
func versionArg(args []string) string {
	if len(args) > 1 {
		return args[1]
	}
	return ""
}

// useColor decides whether to emit ANSI colour: only for a real terminal, and
// only if neither --no-color nor the de-facto NO_COLOR convention objects.
func useColor(cmd *cobra.Command) bool {
	if noColorFlag || os.Getenv("NO_COLOR") != "" {
		return false
	}
	f, ok := cmd.OutOrStdout().(*os.File)
	return ok && term.IsTerminal(int(f.Fd()))
}

// gitopsRepoFlag reads the invoked command's own --gitops-repo, so a completion
// works the same under deploy, deploy promote and deploy sync.
func gitopsRepoFlag(cmd *cobra.Command) string {
	if f := cmd.Flags().Lookup("gitops-repo"); f != nil {
		return f.Value.String()
	}
	return ""
}

// completeDeployComponents suggests component names from the cached GitOps
// checkout. Like the other completions in this package it stays silent on
// error — a shell completion must never print a diagnostic.
func completeDeployComponents(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
	// The second argument is a release version, and listing those means a
	// registry round trip. Every completion here reads the local cache only.
	if len(args) > 0 {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	root, err := gitops.CachedRoot(gitopsRepoFlag(cmd))
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	seen := map[string]bool{}
	var names []string
	for _, c := range gitops.ListComponents(root) {
		if !seen[c.Component] {
			seen[c.Component] = true
			names = append(names, c.Component)
		}
	}
	return names, cobra.ShellCompDirectiveNoFileComp
}

// completeDeployEnvironments suggests environments from the GitOps
// repository's deploy.yaml.
func completeDeployEnvironments(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
	root, err := gitops.CachedRoot(gitopsRepoFlag(cmd))
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	cfg, err := gitops.LoadDeployConfig(root)
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	return cfg.EnvironmentNames(), cobra.ShellCompDirectiveNoFileComp
}

func init() {
	f := deployCmd.Flags()
	f.StringVarP(&deployFlagValues.env, "env", "e", "", "target environment (required)")
	f.StringVar(&deployFlagValues.domain, "domain", "", "disambiguate the component by domain")
	f.StringVar(&deployFlagValues.system, "system", "", "disambiguate the component by system")
	f.StringVar(&deployFlagValues.gitopsRepo, "gitops-repo", "", "GitOps repository URL (default: gitopsRepo from config, or INTROPY_GITOPS_REPO)")
	f.StringVar(&deployFlagValues.argocdServer, "argocd-server", "", "ArgoCD server to watch (default: argocdServer from config, ARGOCD_SERVER, or deploy.yaml)")
	f.BoolVar(&deployFlagValues.plan, "plan", false, "render and diff the change without writing to git")
	f.BoolVar(&deployFlagValues.allowDirty, "allow-dirty", false, "deploy despite uncommitted changes under the component's source paths")
	f.BoolVar(&deployFlagValues.noWait, "no-wait", false, "push without waiting for ArgoCD to sync")
	f.DurationVar(&deployFlagValues.timeout, "timeout", argocd.DefaultTimeout, "how long to wait for ArgoCD to converge")
	f.StringVarP(&deployFlagValues.output, "output", "o", deploy.OutputPlain, "output format (plain, json)")

	_ = deployCmd.MarkFlagRequired("env")
	_ = deployCmd.RegisterFlagCompletionFunc("env", completeDeployEnvironments)
	_ = deployCmd.RegisterFlagCompletionFunc("output", func(*cobra.Command, []string, string) ([]string, cobra.ShellCompDirective) {
		return []string{deploy.OutputPlain, deploy.OutputJSON}, cobra.ShellCompDirectiveNoFileComp
	})

	rootCmd.AddCommand(deployCmd)
}

package release

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/source"
)

// now is the clock, replaced in tests so a manifest is reproducible.
var now = time.Now

// Create publishes an immutable release manifest and pushes an annotated git
// tag. It changes no environment: what was running before is still running,
// and because the version resolves the same commit it resolves the same
// digests.
//
// Re-running for a version that already exists is safe. The existing manifest
// is compared against what this run would publish; if they agree, the release
// is left alone and only a missing git tag is repaired. If they disagree the
// version is being reused for something else, and that is refused.
func Create(ctx context.Context, opts Options) error {
	opts.applyDefaults()

	if opts.Version == "" {
		return errors.New("a version is required")
	}
	if err := command.RequireBinaries("git"); err != nil {
		return err
	}

	cfg, err := config.Load()
	if err != nil {
		return err
	}
	resolved := cfg.Resolve(config.Flags{GitopsRepo: opts.GitopsRepo})
	repoURL, err := resolved.RequireGitopsRepo()
	if err != nil {
		return err
	}

	fmt.Fprintf(opts.Stderr, "refreshing %s\n", repoURL)
	repo, err := gitops.Open(ctx, gitops.Options{URL: repoURL, Runner: opts.Runner, CacheRoot: opts.CacheRoot})
	if err != nil {
		return err
	}
	defer repo.Close()

	coord, err := gitops.FindComponent(repo.Root, opts.Component, opts.Domain, opts.System)
	if err != nil {
		return err
	}
	comp, err := gitops.LoadComponentConfig(gitops.JoinRel(repo.Root, coord.RelPath()))
	if err != nil {
		return err
	}
	if len(comp.Images) == 0 {
		return fmt.Errorf("%s declares no images, so there is nothing to release", coord)
	}

	g := git.Client{Runner: opts.Runner, Dir: opts.SourceDir}

	src, err := source.Inspect(ctx, g, comp.SourcePaths, opts.AllowDirty)
	if err != nil {
		return err
	}
	if len(src.Dirty) > 0 {
		fmt.Fprintf(opts.Stderr, "warning: releasing with %d uncommitted change(s) under the component's source paths\n", len(src.Dirty))
	}

	// Ref defaults to HEAD, which Inspect has already checked. A different ref
	// is resolved here and checked for reachability the same way.
	commit := src.Commit
	if opts.Ref != "HEAD" {
		commit, err = g.RevParse(ctx, opts.Ref)
		if err != nil {
			return fmt.Errorf("resolve --ref %s: %w", opts.Ref, err)
		}
		pushed, err := g.IsAncestor(ctx, commit, gitops.RemoteName+"/"+src.Branch)
		if err != nil {
			return err
		}
		if !pushed {
			return &source.UnpushedCommitError{Commit: commit, Branch: gitops.RemoteName + "/" + src.Branch}
		}
	}

	reg, err := NewRegistry(opts.UserAgent)
	if err != nil {
		return err
	}

	releasesRepo := ReleasesRepo(comp.Images[0].Name)
	ref := Ref(releasesRepo, opts.Version)

	// Look before publishing. A retry after a partial run has to recognise its
	// own earlier work, and that is only possible while the existing manifest
	// is still there to compare against.
	existing, err := lookup(ctx, reg, ref)
	if err != nil {
		return err
	}

	// Registry's Resolve matches source.Resolver, so no adapter is needed.
	pins, err := source.ResolveDigests(ctx, reg, comp, commit)
	if err != nil {
		return err
	}

	basis, from, err := resolveBasis(ctx, reg, g, releasesRepo, commit, opts.Since, opts.Version)
	if err != nil {
		return err
	}

	var changes []Change
	if from != "" {
		if changes, err = Changelog(ctx, g, from, commit, comp.SourcePaths); err != nil {
			return err
		}
	}

	m := &Manifest{
		SchemaVersion: SchemaVersion,
		Component:     coord.Component,
		Version:       opts.Version,
		CreatedAt:     now().UTC().Truncate(time.Second),
		CreatedBy:     committer(),
		Source:        Source{Commit: commit, Ref: opts.Ref, Repo: repoURL},
		Images:        images(pins),
		Changes:       changes,
		ChangeBasis:   basis,
	}
	m.Notes = RenderNotes(changes, basis)

	result := Result{
		Component: m.Component,
		Version:   m.Version,
		Ref:       ref,
		Tag:       TagName(coord.Component, opts.Version),
		Manifest:  m,
	}

	switch {
	case existing == nil:
		digest, err := Push(ctx, reg, ref, m)
		if err != nil {
			return err
		}
		result.Digest, result.Created = digest, true
		fmt.Fprintf(opts.Stderr, "published %s\n", ref)

	case existing.SameRelease(m):
		// Already published, identically. Report the release that exists
		// rather than the one this run would have built.
		desc, err := reg.Resolve(ctx, ref)
		if err != nil {
			return err
		}
		result.Digest, result.Manifest = desc.Digest, existing
		fmt.Fprintf(opts.Stderr, "%s already published; nothing to do\n", ref)

	default:
		return fmt.Errorf("%s already exists and describes a different release (%s vs %s)\n"+
			"a release is immutable: pick a new version, or delete the tag in the registry if it was published in error",
			ref, shortSHA(existing.Source.Commit), shortSHA(m.Source.Commit))
	}

	// Tag after publishing. The manifest is what a release is; the tag is a
	// convenience for people reading git log, and nothing in this CLI reads it
	// — release discovery goes through the registry. So a tag that cannot be
	// pushed is reported and does not fail the command, and re-running repairs
	// it against the manifest that already exists.
	result.Tagged = tag(ctx, g, result.Tag, commit, m, opts.Stderr)

	return report(opts, result)
}

// lookup reads the manifest already published at ref, if any.
func lookup(ctx context.Context, reg Registry, ref string) (*Manifest, error) {
	m, err := Pull(ctx, reg, ref)
	switch {
	case err == nil:
		return m, nil
	case errors.Is(err, ErrNotFound):
		return nil, nil
	case errors.Is(err, ErrNotRelease):
		// Something else holds this tag. Publishing over it would destroy
		// whatever it is.
		return nil, fmt.Errorf("%s already exists and is not a release manifest: %w", ref, err)
	default:
		return nil, err
	}
}

// resolveBasis decides what the changelog is measured against, and returns the
// commit to start from. An empty from means there is nothing to measure.
func resolveBasis(ctx context.Context, reg Registry, g git.Client, releasesRepo, commit, since, version string) (ChangeBasis, string, error) {
	if since != "" {
		from, err := g.RevParse(ctx, since)
		if err != nil {
			return ChangeBasis{}, "", fmt.Errorf("resolve --since %s: %w", since, err)
		}
		ancestor, err := g.IsAncestor(ctx, from, commit)
		if err != nil {
			return ChangeBasis{}, "", err
		}
		if !ancestor {
			return ChangeBasis{}, "", fmt.Errorf("--since %s is not an ancestor of the commit being released (%s), so there is no range between them", since, shortSHA(commit))
		}
		return ChangeBasis{Kind: BasisExplicit, Ref: since}, from, nil
	}

	prev, err := PreviousRelease(ctx, reg, g, releasesRepo, commit, version)
	if err != nil {
		return ChangeBasis{}, "", err
	}
	if prev == nil {
		// Nothing was released, so there is no prior state to diff against.
		// The window is undefined rather than large, and saying so beats
		// synthesising one: the first managed release of a component is
		// usually adoption, not birth, and --since is how an operator names
		// the point the tool cannot know.
		return ChangeBasis{Kind: BasisInitial}, "", nil
	}
	return ChangeBasis{
		Kind:    BasisRelease,
		Version: prev.Version,
		Commit:  prev.Source.Commit,
	}, prev.Source.Commit, nil
}

// TagName is the annotated tag for a release. Component-prefixed because these
// are monorepos: a bare v1.4.2 would collide the moment a second component in
// the same repository cut a release.
func TagName(component, version string) string {
	return component + "/v" + version
}

// tag creates and pushes the annotated tag, reporting whether it reached the
// remote. Every failure is a warning: the release is already published, and
// the tag is not load-bearing.
func tag(ctx context.Context, g git.Client, name, commit string, m *Manifest, stderr io.Writer) bool {
	at, exists, err := g.TagCommit(ctx, name)
	if err != nil {
		fmt.Fprintf(stderr, "warning: could not read tag %s: %v\n", name, err)
		return false
	}

	switch {
	case exists && at != commit:
		fmt.Fprintf(stderr, "warning: tag %s already points at %s, not %s; leaving it alone\n", name, shortSHA(at), shortSHA(commit))
		return false
	case !exists:
		if err := g.Tag(ctx, name, tagMessage(m), commit); err != nil {
			fmt.Fprintf(stderr, "warning: could not create tag %s: %v\n", name, err)
			return false
		}
	}

	// Pushing a tag the remote already has is a no-op, which is what makes
	// this safe to repeat.
	if err := g.Push(ctx, gitops.RemoteName, "refs/tags/"+name); err != nil {
		fmt.Fprintf(stderr, "warning: release %s is published, but its git tag could not be pushed: %v\n", m.Version, err)
		fmt.Fprintf(stderr, "         the release is valid without it; re-run to repair the tag\n")
		return false
	}
	fmt.Fprintf(stderr, "tagged %s\n", name)
	return true
}

func tagMessage(m *Manifest) string {
	return fmt.Sprintf("%s %s\n\n%s", m.Component, m.Version, m.Notes)
}

func images(pins []source.Pin) []Image {
	out := make([]Image, 0, len(pins))
	for _, p := range pins {
		out = append(out, Image{Name: p.Image, Digest: p.Digest})
	}
	return out
}

func committer() string {
	for _, key := range []string{"GITLAB_USER_EMAIL", "GITHUB_ACTOR", "USER"} {
		if v := os.Getenv(key); v != "" {
			return v
		}
	}
	return ""
}

func report(opts Options, r Result) error {
	if opts.OutputFormat == OutputJSON {
		enc := json.NewEncoder(opts.Stdout)
		enc.SetIndent("", "  ")
		return enc.Encode(r)
	}
	return renderCreated(opts.Stdout, r)
}

// Package registry provides a generic OCI registry client: authentication
// via the docker credential store, artifact push/pull, tag/digest
// resolution, and image-index handling. It is policy-free — callers decide
// which artifact types and layouts are acceptable.
package registry

import (
	"context"
	"fmt"
	"net"
	"net/http"

	"oras.land/oras-go/v2/registry/remote"
	"oras.land/oras-go/v2/registry/remote/auth"
	"oras.land/oras-go/v2/registry/remote/credentials"
	"oras.land/oras-go/v2/registry/remote/retry"
)

type Client struct {
	auth      *auth.Client
	plainHTTP func(registry string) bool
}

type options struct {
	httpClient *http.Client
	userAgent  string
	credential func(ctx context.Context, registry string) (auth.Credential, error)
	plainHTTP  func(registry string) bool
}

type Option func(*options)

// WithHTTPClient replaces the default retrying HTTP client.
func WithHTTPClient(c *http.Client) Option {
	return func(o *options) { o.httpClient = c }
}

// WithUserAgent sets the User-Agent header on all registry requests.
func WithUserAgent(ua string) Option {
	return func(o *options) { o.userAgent = ua }
}

// WithCredentials replaces the docker credential store as the credential
// source.
func WithCredentials(f func(ctx context.Context, registry string) (auth.Credential, error)) Option {
	return func(o *options) { o.credential = f }
}

// WithPlainHTTP replaces the default policy for which registries are spoken
// to over plain HTTP (local registries only).
func WithPlainHTTP(f func(registry string) bool) Option {
	return func(o *options) { o.plainHTTP = f }
}

func NewClient(opts ...Option) (*Client, error) {
	o := options{plainHTTP: isLocalRegistry}
	for _, opt := range opts {
		opt(&o)
	}

	credential := o.credential
	if credential == nil {
		store, err := credentials.NewStoreFromDocker(credentials.StoreOptions{})
		if err != nil {
			return nil, fmt.Errorf("load docker credentials: %w", err)
		}
		credential = credentials.Credential(store)
	}

	httpClient := o.httpClient
	if httpClient == nil {
		httpClient = retry.DefaultClient
	}

	authClient := &auth.Client{
		Client:     httpClient,
		Cache:      auth.NewCache(),
		Credential: credential,
	}
	if o.userAgent != "" {
		authClient.SetUserAgent(o.userAgent)
	}

	return &Client{auth: authClient, plainHTTP: o.plainHTTP}, nil
}

func (c *Client) repository(ref Reference) (*remote.Repository, error) {
	repo, err := remote.NewRepository(ref.Registry + "/" + ref.Repository)
	if err != nil {
		return nil, fmt.Errorf("build repository client: %w", err)
	}

	repo.Client = c.auth
	repo.PlainHTTP = c.plainHTTP(ref.Registry)

	return repo, nil
}

// isLocalRegistry follows the same convention as docker and the oras CLI:
// local registries speak plain HTTP without an explicit opt-in.
func isLocalRegistry(registry string) bool {
	host := registry
	if h, _, err := net.SplitHostPort(registry); err == nil {
		host = h
	}
	return host == "localhost" || host == "127.0.0.1" || host == "::1"
}

package source

import (
	"context"
	"errors"
	"fmt"

	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/registry"
)

// CommitTagPrefix is prepended to a commit sha to form the image tag CI
// publishes. Kept in one place: if the pipeline's tagging scheme ever differs,
// this is the only line that changes.
const CommitTagPrefix = "sha-"

// CommitTag returns the registry tag for a commit.
func CommitTag(commit string) string { return CommitTagPrefix + commit }

// Pin is one image repository resolved to an immutable digest.
type Pin struct {
	// Image is the bare repository, as declared in component.yaml.
	Image string

	// Digest is the manifest digest, in sha256:… form.
	Digest string

	// Tag is the tag the digest was resolved from, kept for messages.
	Tag string
}

// Ref renders the pinned reference in the form kustomize writes.
func (p Pin) Ref() string { return p.Image + "@" + p.Digest }

// Resolver resolves an image reference to a descriptor. It is the seam that
// lets digest resolution be tested against an in-memory registry.
type Resolver interface {
	Resolve(ctx context.Context, ref string) (registry.Descriptor, error)
}

// NewResolver builds the production resolver. Replaced in tests, following the
// newSkillRegistry pattern in cmd/intropy.
var NewResolver = func(userAgent string) (Resolver, error) {
	return registry.NewClient(registry.WithUserAgent(userAgent))
}

// ResolveDigests resolves every image in the component to the digest CI
// published for commit.
//
// The digest comes from whatever the registry actually returns for the tag,
// which is the point of resolving rather than constructing a reference: for a
// multi-architecture build the tag points at an image index, and the index
// digest is what must be pinned. Registries have also been known to convert
// between Docker and OCI manifest types on read, changing the digest, so the
// only safe value is the one this lookup observed.
func ResolveDigests(ctx context.Context, r Resolver, comp *gitops.ComponentConfig, commit string) ([]Pin, error) {
	tag := CommitTag(commit)

	pins := make([]Pin, 0, len(comp.Images))
	for _, img := range comp.Images {
		ref := img.Name + ":" + tag
		desc, err := r.Resolve(ctx, ref)
		if err != nil {
			return nil, resolveError(err, img.Name, tag)
		}
		if desc.Digest == "" {
			return nil, fmt.Errorf("registry returned no digest for %s", ref)
		}
		pins = append(pins, Pin{Image: img.Name, Digest: desc.Digest, Tag: tag})
	}
	return pins, nil
}

// resolveError turns a registry failure into something a caller can act on.
// A missing tag is the single most common case by far — it means the pipeline
// has not finished publishing — and deserves to say so rather than read as a
// generic 404.
func resolveError(err error, image, tag string) error {
	if errors.Is(err, registry.ErrNotFound) {
		return fmt.Errorf("%s has no %s tag yet: the pipeline has not published an image for this commit (or was not triggered for it)", image, tag)
	}
	return fmt.Errorf("resolve %s:%s: %w", image, tag, err)
}

// Package deploy orchestrates a deployment: it resolves which image digest a
// commit produced, pins it into one environment's overlay in the GitOps
// repository, and reports what changed.
//
// The mechanics live in narrower packages — command, git, gitops, kustomize,
// registry, release and source — and this package is the policy that combines
// them.
package deploy

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/integrio-intropy/intropy-cli/internal/argocd"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/kustomize"
)

// Run resolves the digests to deploy — from a release manifest when Version is
// set, otherwise from the current commit — and pins them into one
// environment's overlay.
//
// With PlanOnly set it stops after the diff, having written nothing. Otherwise
// it commits, pushes, and waits for ArgoCD to converge unless the environment
// syncs manually or NoWait is set.
func Run(ctx context.Context, opts Options) error {
	opts.applyDefaults()

	s, err := openSession(ctx, opts.session(), "git", "kustomize")
	if err != nil {
		return err
	}
	defer s.Close()
	repo, deployCfg := s.repo, s.deployCfg

	env, err := deployCfg.Environment(opts.Environment)
	if err != nil {
		return err
	}

	coord, comp, err := s.locateComponent(opts.Component, opts.Domain, opts.System)
	if err != nil {
		return err
	}
	if err := requirePinnable(coord, comp); err != nil {
		return err
	}
	overlayDir, err := gitops.ResolveOverlay(repo.Root, coord, comp, opts.Environment)
	if err != nil {
		return err
	}

	org, err := resolveOrigin(ctx, opts, coord, comp)
	if err != nil {
		return err
	}

	out := opts.output()
	plan, err := BuildPlan(ctx, PlanOptions{
		Repository:     repo,
		Kustomize:      kustomize.Client{Runner: opts.Runner},
		Coordinate:     coord,
		Environment:    opts.Environment,
		Source:         org.State,
		ReleaseVersion: org.ReleaseVersion(),
		Pins:           org.Pins,
		Upstreams:      InspectUpstreams(repo.Root, coord, comp, opts.Environment, env, org.Pins),
		OverlayDir:     overlayDir,
		Palette:        out.palette(),
	})
	if err != nil {
		return err
	}

	// An empty plan already reverted itself, and --plan must leave no trace, so
	// only the apply path proceeds past here.
	if plan.Empty() || opts.PlanOnly {
		if opts.PlanOnly && !plan.Empty() {
			defer revertOverlay(ctx, out, plan, repo)
		}
		return report(out, plan, coord, env, "", nil)
	}

	// Print the plan before writing anything, so the diff is on screen even if
	// the push then fails. Not in JSON mode: there the encoded result is the
	// program output, and a diff on the same stream would make it unparseable.
	if out.Format == OutputPlain {
		reportPlan(out, plan)
	}

	revision, err := Publish(ctx, PublishOptions{
		Repository: repo,
		Plan:       plan,
		CliVersion: opts.UserAgent,
		Stderr:     opts.Stderr,
	})
	if err != nil {
		// Publish leaves nothing pushed on failure, but the local commit may
		// exist; the checkout is hard-reset on the next run either way.
		return err
	}
	fmt.Fprintf(opts.Stderr, "pushed %s to %s\n", git.ShortSHA(revision), repo.Branch)

	// A manual-sync environment is gated in ArgoCD, so there is no sync to wait
	// for; --no-wait opts out everywhere else.
	if opts.NoWait || env.Sync == gitops.SyncManual {
		return report(out, plan, coord, env, revision, nil)
	}

	app, observed, err := WaitForSync(ctx, WaitOptions{
		Repository:   repo,
		DeployCfg:    deployCfg,
		AppName:      coord.AppName(opts.Environment),
		Revision:     revision,
		Timeout:      opts.Timeout,
		ArgocdServer: opts.ArgocdServer,
		ConfigServer: s.argocdServer,
		UserAgent:    opts.UserAgent,
		Stderr:       opts.Stderr,
	})
	if err != nil {
		return err
	}
	if !observed {
		app = nil
	}
	return report(out, plan, coord, env, revision, app)
}

func componentDir(root string, c gitops.Coordinate) string {
	return gitops.JoinRel(root, c.RelPath())
}

// revertOverlay discards the plan's overlay edits, warning if it cannot. The
// cached checkout is shared between runs, so leaving it dirty would poison the
// next one.
func revertOverlay(ctx context.Context, out output, plan *Plan, repo *gitops.Repository) {
	if err := plan.Revert(ctx, repo); err != nil {
		fmt.Fprintf(out.Stderr, "warning: could not revert the overlay edit: %v\n", err)
	}
}

// reportPlan writes the human summary and diff to stdout.
func reportPlan(out output, plan *Plan) {
	fmt.Fprint(out.Stdout, plan.Summary())
	if plan.ProvenanceOnly() {
		// kustomize propagates commonAnnotations into pod templates, so this
		// still restarts the pods. Say so rather than let it surprise anyone.
		fmt.Fprintf(out.Stdout, "\nno image digest changed; only the source-commit annotation moves.\nthis still restarts the pods, because kustomize applies commonAnnotations to pod templates.\n")
	}
	fmt.Fprintf(out.Stdout, "\n%s", plan.Diff)
}

// report writes the final outcome. revision is the pushed sha, empty when
// nothing was pushed.
func report(out output, plan *Plan, coord gitops.Coordinate, env gitops.EnvironmentConfig, revision string, app *argocd.Application) error {
	if out.Format == OutputJSON {
		return writeJSON(out, plan, coord, env, revision, app)
	}

	// Already there. Still print the upstream comparison: "staging is already
	// running the digest dev tested" is the most reassuring form of this
	// message, and suppressing it would withhold the answer to the question
	// that prompted the command.
	if plan.Empty() {
		fmt.Fprintf(out.Stdout, "%s is already at %s in %s; nothing to do\n",
			coord, plan.pinnedAs(), plan.Environment)
		fmt.Fprint(out.Stdout, plan.noteLines())
		return nil
	}

	if revision == "" {
		reportPlan(out, plan)
		fmt.Fprintf(out.Stderr, "\nplan only: nothing was committed\n")
		return nil
	}

	// A manual-sync environment is gated in ArgoCD, so the commit is as far as
	// a deploy can take it. Waiting would hang on a sync that never starts.
	if env.Sync == gitops.SyncManual {
		// Both commands, and the sha --revision wants. The gate is a second person
		// reading the rendered change, and telling them only the command to apply it
		// leaves them to find the revision they are approving for themselves.
		fmt.Fprintf(out.Stdout, "\ncommitted %s to %s. %s syncs manually, so nothing is applied yet:\n"+
			"  intropy deploy diff %s --env %s\n"+
			"  intropy deploy sync %s --env %s --revision %s\n",
			git.ShortSHA(revision), plan.Environment, plan.Environment,
			coord.Component, plan.Environment,
			coord.Component, plan.Environment, revision)
		return nil
	}

	if app != nil {
		fmt.Fprintf(out.Stdout, "\ncommitted %s; %s is synced and healthy at %s\n",
			git.ShortSHA(revision), coord.AppName(plan.Environment), shortDigest(app.Status.Sync.Revision))
		return nil
	}
	fmt.Fprintf(out.Stdout, "\ncommitted %s; ArgoCD will sync %s\n", git.ShortSHA(revision), coord.AppName(plan.Environment))
	return nil
}

func writeJSON(out output, plan *Plan, coord gitops.Coordinate, env gitops.EnvironmentConfig, revision string, app *argocd.Application) error {
	res := Result{
		Component:    coord.Component,
		Domain:       coord.Domain,
		System:       coord.System,
		Environment:  plan.Environment,
		SourceCommit: plan.Source.Commit,
		AppName:      coord.AppName(plan.Environment),
		OverlayPath:  coord.OverlayRelPath(plan.Environment),
		Changed:      !plan.Empty(),
		Applied:      revision != "",
		Revision:     revision,
		Upstreams:    plan.Upstreams,
		SyncPolicy:   env.Sync,
	}
	res.Release = plan.ReleaseVersion
	res.PromotedFrom = plan.PromotedFrom
	if app != nil {
		res.SyncStatus = app.Status.Sync.Status
		res.HealthStatus = app.Status.Health.Status
		res.SyncedRevision = app.Status.Sync.Revision
	}
	for _, pin := range plan.Pins {
		res.Pins = append(res.Pins, ResultPin{
			Image:    pin.Image,
			Previous: plan.Previous[pin.Image],
			Digest:   pin.Digest,
			Tag:      pin.Tag,
		})
	}

	enc := json.NewEncoder(out.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(res); err != nil {
		return fmt.Errorf("write JSON result: %w", err)
	}
	return nil
}

package deploy

import (
	"context"
	"errors"
	"fmt"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/release"
	"github.com/integrio-intropy/intropy-cli/internal/source"
)

// origin is where the digests being deployed came from.
type origin struct {
	// State is the source state to record with the deployment. For a release
	// deploy only Commit is populated, read from the manifest: Branch and
	// Dirty describe a working tree, and a release deploy reads none. Nothing
	// downstream needs them — the overlay annotation, the commit subject and
	// the trailers all want the commit alone.
	State source.State

	// Pins is one pin per image declared in component.yaml, in that order.
	Pins []source.Pin

	// Release is the manifest the pins came from, nil when the digests were
	// resolved from the source repository's HEAD.
	Release *release.Manifest
}

// ReleaseVersion is the version the pins came from, empty for a commit deploy.
func (o origin) ReleaseVersion() string {
	if o.Release == nil {
		return ""
	}
	return o.Release.Version
}

// resolveOrigin decides which digests are being deployed.
//
// Without a version this is the current commit: HEAD must be clean and pushed,
// and the digests come from the tags CI published for it. With a version the
// release manifest is authoritative — it already recorded the digests it was
// created by resolving — so no source repository is consulted at all and the
// command works from any directory.
func resolveOrigin(ctx context.Context, opts Options, coord gitops.Coordinate, comp *gitops.ComponentConfig) (origin, error) {
	if opts.Version != "" {
		return resolveFromRelease(ctx, opts, coord, comp)
	}
	return resolveFromHEAD(ctx, opts, comp)
}

// resolveFromHEAD reads the current commit and asks the registry what CI built
// for it.
func resolveFromHEAD(ctx context.Context, opts Options, comp *gitops.ComponentConfig) (origin, error) {
	src, err := source.Inspect(ctx, git.Client{Runner: opts.Runner, Dir: opts.SourceDir}, comp.SourcePaths, opts.AllowDirty)
	if err != nil {
		return origin{}, err
	}
	if len(src.Dirty) > 0 {
		fmt.Fprintf(opts.Stderr, "warning: deploying with %d uncommitted change(s) under the component's source paths\n", len(src.Dirty))
	}

	resolver, err := source.NewResolver(opts.UserAgent)
	if err != nil {
		return origin{}, err
	}
	fmt.Fprintf(opts.Stderr, "resolving %s\n", source.CommitTag(src.ShortCommit()))
	pins, err := source.ResolveDigests(ctx, resolver, comp, src.Commit)
	if err != nil {
		return origin{}, err
	}
	return origin{State: src, Pins: pins}, nil
}

// resolveFromRelease reads the digests a published release recorded.
//
// This is the whole reason a release exists: the manifest is immutable, so the
// digests in it are exactly the bits that were tested, and pinning them needs
// neither the source repository nor a second registry lookup.
func resolveFromRelease(ctx context.Context, opts Options, coord gitops.Coordinate, comp *gitops.ComponentConfig) (origin, error) {
	if len(comp.Images) == 0 {
		return origin{}, fmt.Errorf("%s declares no images, so it has no releases", coord)
	}

	reg, err := release.NewRegistry(opts.UserAgent)
	if err != nil {
		return origin{}, err
	}

	releasesRepo := release.ReleasesRepo(comp.Images[0].Name)
	ref := release.Ref(releasesRepo, opts.Version)
	fmt.Fprintf(opts.Stderr, "reading %s\n", ref)

	m, err := release.Pull(ctx, reg, ref)
	if err != nil {
		if errors.Is(err, release.ErrNotFound) {
			return origin{}, releaseNotFoundError(ctx, reg, err, coord, releasesRepo, opts.Version)
		}
		return origin{}, err
	}
	// The OCI tag is how the operator selected this release, while Version is
	// the manifest's self-description. Both must agree: accepting a manifest
	// copied or retagged under a different version would deploy and record a
	// release other than the one the command line named.
	if m.Version != opts.Version {
		return origin{}, fmt.Errorf("%s is tagged as release %s, but its manifest declares version %s", ref, opts.Version, m.Version)
	}

	pins, extra, err := pinsFromManifest(m, comp, coord, ref)
	if err != nil {
		return origin{}, err
	}
	for _, image := range extra {
		fmt.Fprintf(opts.Stderr, "warning: release %s also records %s, which %s no longer declares in %s; it will not be pinned\n",
			m.Version, image, coord.Component, gitops.ComponentFileName)
	}

	return origin{State: source.State{Commit: m.Source.Commit}, Pins: pins, Release: m}, nil
}

// pinsFromManifest matches the digests a release recorded against the images
// component.yaml declares.
//
// It iterates comp.Images rather than the manifest's, which is what keeps the
// pin order identical to the HEAD path — report and commitSubject index
// Pins[0], and a deploy should pin what the component declares today.
//
// extra names images the release recorded that the component no longer
// declares. That is a warning rather than a failure: dropping an image is a
// normal thing to do, and refusing would make every earlier release
// undeployable.
func pinsFromManifest(m *release.Manifest, comp *gitops.ComponentConfig, coord gitops.Coordinate, ref string) (pins []source.Pin, extra []string, err error) {
	if m.Component != coord.Component {
		return nil, nil, fmt.Errorf("%s describes component %q, not %q.\nThe releases repository is derived from images[0].name in %s, so two components sharing an image repository collide here",
			ref, m.Component, coord.Component, gitops.ComponentFileName)
	}

	digests := make(map[string]string, len(m.Images))
	for _, img := range m.Images {
		digests[img.Name] = img.Digest
	}

	pins = make([]source.Pin, 0, len(comp.Images))
	for _, img := range comp.Images {
		digest, ok := digests[img.Name]
		if !ok {
			return nil, nil, fmt.Errorf("release %s has no digest for %s, which %s declares in %s.\nThe release was cut before that image existed — cut a new one with 'intropy release create %s --version <next>', or deploy the current commit instead",
				m.Version, img.Name, coord.Component, gitops.ComponentFileName, coord.Component)
		}
		// Tag is deliberately empty: it means "the tag this digest was
		// resolved from", and a release deploy resolved nothing from a tag.
		// Filling in sha-<commit> would assert a registry state never observed.
		pins = append(pins, source.Pin{Image: img.Name, Digest: digest})
		delete(digests, img.Name)
	}

	for name := range digests {
		extra = append(extra, name)
	}
	slices.Sort(extra)
	return pins, extra, nil
}

// releaseNotFoundError explains a version that was never published, and lists
// the ones that were.
//
// The listing is decoration on an error path, so its own failure is swallowed:
// being unable to enumerate versions is no reason to replace a clear message
// with an obscure one.
func releaseNotFoundError(ctx context.Context, reg release.Registry, cause error, coord gitops.Coordinate, releasesRepo, version string) error {
	var b strings.Builder
	fmt.Fprintf(&b, "release %s of %s does not exist in %s", version, coord.Component, releasesRepo)
	if versions, err := release.ListVersions(ctx, reg, releasesRepo); err == nil && len(versions) > 0 {
		slices.Sort(versions)
		fmt.Fprintf(&b, "\npublished versions: %s", strings.Join(versions, ", "))
	} else {
		fmt.Fprintf(&b, "\nnothing has been released for %s yet", coord.Component)
	}
	fmt.Fprintf(&b, "\ncreate it from the source repository: intropy release create %s --version %s", coord.Component, version)
	return fmt.Errorf("%w: %s", cause, b.String())
}

package deploy

import (
	"cmp"
	"context"
	"errors"
	"fmt"
	"io"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/argocd"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
)

// NewArgoClient builds the production ArgoCD client. Replaced in tests.
var NewArgoClient = func(opts argocd.Options) (ArgoClient, error) {
	return argocd.NewClient(opts)
}

// ArgoClient is the part of the ArgoCD client this package needs: a deploy
// waits, a promotion reads the source application's health, a sync applies a
// revision, and a diff renders two of them.
type ArgoClient interface {
	Get(ctx context.Context, app string) (*argocd.Application, error)
	Sync(ctx context.Context, app, revision string) error
	Wait(ctx context.Context, opts argocd.WaitOptions) (*argocd.Application, error)
	Manifests(ctx context.Context, app, revision string) (*argocd.ManifestResponse, error)
}

// connect builds a client for the ArgoCD instance that reconciles this
// repository, resolving the server the same way everywhere: the flag wins, then
// ARGOCD_SERVER, then deploy.yaml, and finally the user's configuration file.
//
// deploy.yaml beats the user configuration on purpose — it travels with the
// repository the overlays live in.
func connect(deployCfg *gitops.DeployConfig, serverFlag, configServer, userAgent string) (ArgoClient, argocd.Credentials, error) {
	creds, err := argocd.LoadCredentials(argocd.ResolveServer(serverFlag, cmp.Or(deployCfg.Argocd.Server, configServer)))
	if err != nil {
		return nil, creds, err
	}
	client, err := NewArgoClient(argocd.Options{
		Credentials:  creds,
		AppNamespace: deployCfg.Argocd.AppNamespace,
		UserAgent:    userAgent,
	})
	if err != nil {
		return nil, creds, err
	}
	return client, creds, nil
}

// WaitOptions configures WaitForSync.
type WaitOptions struct {
	Repository *gitops.Repository
	DeployCfg  *gitops.DeployConfig
	AppName    string
	Revision   string
	Timeout    time.Duration

	// ArgocdServer is the --argocd-server flag, which wins over everything.
	ArgocdServer string

	// ConfigServer is argocdServer from the user's configuration file. It is
	// the last resort: deploy.yaml wins over it, because that file travels
	// with the repository the overlays live in.
	ConfigServer string

	UserAgent string
	Stderr    io.Writer
}

// WaitForSync waits for ArgoCD to apply the pushed revision.
//
// The returned bool reports whether ArgoCD was actually observed. False with a
// nil error means it could not be reached — which is not a deployment failure:
// the commit is the deployment, and being unable to watch does not undo it.
func WaitForSync(ctx context.Context, opts WaitOptions) (*argocd.Application, bool, error) {
	client, creds, err := connect(opts.DeployCfg, opts.ArgocdServer, opts.ConfigServer, opts.UserAgent)
	if err != nil {
		// No credentials, or a client that cannot be built, is a setup problem
		// rather than a failed deployment.
		fmt.Fprintf(opts.Stderr, "warning: not waiting for ArgoCD: %v\n", err)
		return nil, false, nil
	}

	fmt.Fprintf(opts.Stderr, "waiting for %s on %s\n", opts.AppName, creds.Server)

	app, err := client.Wait(ctx, argocd.WaitOptions{
		App:      opts.AppName,
		Revision: opts.Revision,
		Timeout:  opts.Timeout,
		Contains: revisionContains(opts.Repository),
		Stderr:   opts.Stderr,
	})
	if err != nil {
		// Not being able to reach ArgoCD after a successful push is a warning:
		// the change is committed and ArgoCD will apply it whenever it can.
		if errors.Is(err, argocd.ErrUnreachable) {
			fmt.Fprintf(opts.Stderr, "warning: %v\n", err)
			fmt.Fprintf(opts.Stderr, "the commit is pushed, so the deployment stands; only the wait was skipped\n")
			return nil, false, nil
		}
		return app, true, err
	}
	return app, true, nil
}

// revisionContains answers whether the revision ArgoCD applied includes ours.
//
// Equality is the common case, but not the only success: if another deployment
// lands after ours, ArgoCD syncs a descendant commit and our sha never appears
// on its own. Asking whether ours is an ancestor is what stops the wait hanging
// forever in that case.
//
// The reported revision may not be in the local clone yet — it can be someone
// else's push — so a miss triggers a fetch before concluding anything.
func revisionContains(repo *gitops.Repository) func(context.Context, string, string) (bool, error) {
	return func(ctx context.Context, mine, reported string) (bool, error) {
		if reported == "" {
			return false, nil
		}
		if reported == mine {
			return true, nil
		}

		contains, err := repo.Git.IsAncestor(ctx, mine, reported)
		if err == nil {
			return contains, nil
		}

		// Most likely the reported commit is not local yet.
		if ferr := repo.Git.Fetch(ctx, gitops.RemoteName, repo.Branch); ferr != nil {
			return false, nil
		}
		contains, err = repo.Git.IsAncestor(ctx, mine, reported)
		if err != nil {
			// Still unknown: treat as not-yet rather than failing the wait on a
			// revision we cannot inspect.
			return false, nil
		}
		return contains, nil
	}
}

package registry

import (
	"cmp"
	"context"
	"encoding/json"
	"fmt"

	ocispec "github.com/opencontainers/image-spec/specs-go/v1"
	"oras.land/oras-go/v2/content"
)

// Resolve returns the descriptor for the manifest at ref, including its
// annotations. ref may carry a tag or a digest.
func (c *Client) Resolve(ctx context.Context, ref string) (Descriptor, error) {
	parsed, err := ParseReference(ref)
	if err != nil {
		return Descriptor{}, fmt.Errorf("parse ref: %w", err)
	}

	repo, err := c.repository(parsed)
	if err != nil {
		return Descriptor{}, err
	}

	desc, err := repo.Resolve(ctx, parsed.TagOrDigest())
	if err != nil {
		return Descriptor{}, mapError(err, parsed)
	}

	manifestBytes, err := content.FetchAll(ctx, repo, desc)
	if err != nil {
		return Descriptor{}, fmt.Errorf("fetch manifest %s: %w", ref, mapError(err, parsed))
	}
	var manifest ocispec.Manifest
	if err := json.Unmarshal(manifestBytes, &manifest); err != nil {
		return Descriptor{}, fmt.Errorf("parse manifest %s: %w", ref, err)
	}

	return Descriptor{
		MediaType: desc.MediaType,
		// The manifest body is authoritative for its own artifact type. A
		// descriptor built from a tag resolution carries only what the
		// registry's headers said, which is media type, digest and size — so
		// without this the field would silently always be empty here.
		ArtifactType: cmp.Or(manifest.ArtifactType, desc.ArtifactType),
		Digest:       desc.Digest.String(),
		Size:         desc.Size,
		Annotations:  manifest.Annotations,
	}, nil
}

package deploy

import (
	"io"
	"os"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/kustomize"
)

const (
	OutputPlain = "plain"
	OutputJSON  = "json"
)

// output is where a command writes, and in what form. Every command in this
// package reports the same way, so the reporting takes this rather than one of
// the three Options types.
type output struct {
	Format string
	Color  bool
	Stdout io.Writer
	Stderr io.Writer
}

// palette picks the diff colouring.
func (o output) palette() kustomize.Palette {
	if o.Color {
		return kustomize.ColorPalette
	}
	return kustomize.PlainPalette
}

// Options configures Run.
type Options struct {
	// Component is the component name; Domain and System disambiguate it when
	// the name occurs more than once.
	Component string
	Domain    string
	System    string

	// Environment is the target environment. Required.
	Environment string

	// Version selects a published release to deploy. Empty means the current
	// commit in SourceDir.
	//
	// With a version the release manifest is authoritative: it already records
	// the digests, so no source repository is read at all and the command works
	// from any directory. AllowDirty is meaningless in that mode, and the
	// command rejects the combination rather than ignoring it.
	Version string

	// GitopsRepo overrides the configured GitOps repository URL.
	GitopsRepo string

	// SourceDir is the source repository to read HEAD from; defaults to the
	// working directory.
	SourceDir string

	// PlanOnly stops after the diff, writing nothing to git.
	PlanOnly bool

	// AllowDirty permits uncommitted changes under the component's sourcePaths.
	AllowDirty bool

	// NoWait skips the ArgoCD wait after pushing.
	NoWait bool

	// Timeout bounds the ArgoCD wait. Zero means the package default.
	Timeout time.Duration

	// ArgocdServer overrides deploy.yaml's argocd.server.
	ArgocdServer string

	// OutputFormat is "plain" or "json".
	OutputFormat string

	// Color enables ANSI colour in the diff.
	Color bool

	// CacheRoot overrides where GitOps checkouts are cached.
	CacheRoot string

	Runner    command.Runner
	UserAgent string
	Stdout    io.Writer
	Stderr    io.Writer
