// resolveError turns a registry failure into something a caller can act on.
// A missing tag is the single most common case by far — it means the pipeline
// has not finished publishing — and deserves to say so rather than read as a
// generic 404.
func resolveError(err error, image, tag string) error {
	if errors.Is(err, registry.ErrNotFound) {
		// The sentinel stays wrapped underneath the friendly message: the
		// watch loop recognises the retryable case with errors.Is, without
		// the message growing a "registry: not found: <ref>" tail.
		return &notPublishedError{image: image, tag: tag}
	}
	return fmt.Errorf("resolve %s:%s: %w", image, tag, err)
}

// notPublishedError reports the tag CI has not published yet. It unwraps to
// registry.ErrNotFound so errors.Is finds the sentinel, but its message is
// written for the operator, not inherited from the registry's wording.
type notPublishedError struct {
	image string
	tag   string
}

func (e *notPublishedError) Error() string {
	return fmt.Sprintf("%s has no %s tag yet: the pipeline has not published an image for this commit (or was not triggered for it)", e.image, e.tag)
}

func (e *notPublishedError) Unwrap() error { return registry.ErrNotFound }

